import { z } from "zod"

import type { notes } from "@/lib/db/schema/notes-table"

/** Inferred from the table - import this instead of redeclaring the row shape. */
export type Note = typeof notes.$inferSelect

export const createNoteInput = z.object({
  title: z.string().trim().min(1).max(200),
  body: z.string().trim().max(10_000).optional(),
})

export const updateNoteInput = createNoteInput.extend({
  id: z.string().min(1),
})

export const deleteNoteInput = z.object({
  id: z.string().min(1),
})

export type CreateNoteInput = z.infer<typeof createNoteInput>

/// <reference types="bun" />
import { describe, expect, test } from "bun:test"

import { createNoteInput, deleteNoteInput, updateNoteInput } from "@/lib/notes/schemas"

describe("createNoteInput", () => {
  test("trims the title and keeps the body optional", () => {
    const result = createNoteInput.parse({ title: "  first note  " })
    expect(result.title).toBe("first note")
    expect(result.body).toBeUndefined()
  })

  test("rejects a title that is only whitespace", () => {
    const result = createNoteInput.safeParse({ title: "   " })
    expect(result.success).toBe(false)
  })

  test("rejects a title over 200 chars", () => {
    const result = createNoteInput.safeParse({ title: "x".repeat(201) })
    expect(result.success).toBe(false)
  })
})

describe("updateNoteInput", () => {
  test("requires an id and applies the create rules to the title", () => {
    expect(updateNoteInput.safeParse({ title: "ok" }).success).toBe(false)
    expect(updateNoteInput.safeParse({ id: "abc", title: "   " }).success).toBe(false)
    expect(updateNoteInput.parse({ id: "abc", title: " ok " }).title).toBe("ok")
  })
})

describe("deleteNoteInput", () => {
  test("requires a non-empty id", () => {
    expect(deleteNoteInput.safeParse({ id: "" }).success).toBe(false)
    expect(deleteNoteInput.safeParse({ id: "abc" }).success).toBe(true)
  })
})

import { notFound } from "@tanstack/react-router"
import { createServerFn } from "@tanstack/react-start"
import { and, desc, eq } from "drizzle-orm"

import { requireUser } from "@/lib/auth/server"
import { getDb } from "@/lib/db"
import { notes } from "@/lib/db/schema/notes-table"
import { createNoteInput, deleteNoteInput, updateNoteInput } from "@/lib/notes/schemas"

/**
 * Ownership pattern: copy it for every user-owned table. Scope reads and writes by `notes.userId`,
 * never by id alone. The owner comes from the session, never from the client.
 * A lock must filter by owner in the same query (`.agents/data-access.md`).
 */

export const $listNotes = createServerFn({ method: "GET" }).handler(async () => {
  const user = await requireUser()
  return getDb()
    .select()
    .from(notes)
    .where(eq(notes.userId, user.id))
    .orderBy(desc(notes.createdAt))
})

export const $createNote = createServerFn({ method: "POST" })
  .validator(createNoteInput)
  .handler(async ({ data }) => {
    const user = await requireUser()
    const [row] = await getDb()
      .insert(notes)
      .values({
        id: crypto.randomUUID(),
        userId: user.id,
        title: data.title,
        body: data.body ?? "",
      })
      .returning()
    return row
  })

export const $updateNote = createServerFn({ method: "POST" })
  .validator(updateNoteInput)
  .handler(async ({ data }) => {
    const user = await requireUser()
    const rows = await getDb()
      .update(notes)
      .set({ title: data.title, body: data.body ?? "" })
      .where(and(eq(notes.id, data.id), eq(notes.userId, user.id)))
      .returning()
    const row = rows.at(0)
    // Someone else's id matches no row, which is indistinguishable from a missing one.
    if (!row) throw notFound()
    return row
  })

export const $deleteNote = createServerFn({ method: "POST" })
  .validator(deleteNoteInput)
  .handler(async ({ data }) => {
    const user = await requireUser()
    // The owner check lives in the WHERE clause: someone else's id simply matches no row.
    await getDb()
      .delete(notes)
      .where(and(eq(notes.id, data.id), eq(notes.userId, user.id)))
    return { ok: true as const }
  })

import { getRouteApi, useRouter } from "@tanstack/react-router"
import { useServerFn } from "@tanstack/react-start"
import { useState } from "react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import type { Note } from "@/lib/notes/schemas"
import { $createNote, $deleteNote, $updateNote } from "@/lib/notes/server"

const route = getRouteApi("/_authed/notes")

/** One note: shows the title, or a rename form (Enter saves, Escape cancels, labelled for screen readers). */
function NoteRow({ note }: { note: Note }) {
  const router = useRouter()
  const updateNote = useServerFn($updateNote)
  const deleteNote = useServerFn($deleteNote)
  const [draft, setDraft] = useState<string | null>(null)

  async function save(event: React.SubmitEvent<HTMLFormElement>) {
    event.preventDefault()
    if (draft?.trim()) await updateNote({ data: { id: note.id, title: draft, body: note.body } })
    setDraft(null)
    await router.invalidate()
  }

  async function remove() {
    await deleteNote({ data: { id: note.id } })
    await router.invalidate()
  }

  return (
    <li className="flex items-center justify-between gap-4 rounded-lg border border-border px-3 py-2">
      {draft === null ? (
        <>
          <span className="text-sm">{note.title}</span>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => setDraft(note.title)}>
              Rename
            </Button>
            <Button variant="destructive" size="sm" onClick={() => void remove()}>
              Delete
            </Button>
          </div>
        </>
      ) : (
        <form className="flex w-full gap-2" onSubmit={(e) => void save(e)}>
          <Input
            ref={(el) => el?.focus()}
            aria-label={`Rename note ${note.title}`}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Escape") setDraft(null)
            }}
          />
          <Button type="submit" size="sm">
            Save
          </Button>
        </form>
      )}
    </li>
  )
}

/**
 * Loader data + `router.invalidate()` is the default data flow here - no client cache to keep in
 * sync. `useServerFn` is what makes a redirect thrown by the auth gate actually navigate.
 */
export function NotesPage() {
  const notes = route.useLoaderData()
  const router = useRouter()
  const createNote = useServerFn($createNote)
  const [title, setTitle] = useState("")

  async function add(event: React.SubmitEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!title.trim()) return
    await createNote({ data: { title } })
    setTitle("")
    await router.invalidate()
  }

  return (
    <section className="flex flex-col gap-6">
      <h1 className="text-xl font-semibold tracking-tight">Notes</h1>

      <form className="flex gap-2" onSubmit={(e) => void add(e)}>
        <Input
          aria-label="Note title"
          placeholder="New note…"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <Button type="submit">Add</Button>
      </form>

      {notes.length === 0 ? (
        <p className="text-sm text-muted-foreground">No notes yet.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {notes.map((note) => (
            <NoteRow key={note.id} note={note} />
          ))}
        </ul>
      )}
    </section>
  )
}

